#include <cstdio>
#include <algorithm>
using namespace std;

const int INF = 1000000;

int main() {
    int n, m, a, b, cost, time, k, p, q, r;
    int t[100][100], c[100][100];

    for (;;) {
        scanf("%d %d", &n, &m);
        if (!n && !m) break;

        fill(&t[0][0], &t[0][0] + sizeof(t) / sizeof(int), INF);
        fill(&c[0][0], &c[0][0] + sizeof(c) / sizeof(int), INF);

        for (int i = 0; i < m; i++) {
            t[i][i] = 0;
            c[i][i] = 0;
        }

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d %d", &a, &b, &cost, &time);
            t[a - 1][b - 1] = min(t[a - 1][b - 1], time);
            t[b - 1][a - 1] = min(t[b - 1][a - 1], time);
            c[a - 1][b - 1] = min(c[a - 1][b - 1], cost);
            c[b - 1][a - 1] = min(c[b - 1][a - 1], cost);
        }

        for (int x = 0; x < m; x++) {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < m; j++) {
                    if (t[i][j] > t[i][x] + t[x][j]) {
                        t[i][j] = t[i][x] + t[x][j];
                    }
                    if (c[i][j] > c[i][x] + c[x][j]) {
                        c[i][j] = c[i][x] + c[x][j];
                    }
                }
            }
        }

        scanf("%d", &k);
        for (int i = 0; i < k; i++) {
            scanf("%d %d %d", &p, &q, &r);
            if (r) printf("%d\n", t[p - 1][q - 1]);
            else printf("%d\n", c[p - 1][q - 1]);
        }
    }
}

